  function renderMovement() { const width=680,height=390; const node=svg($('#movementChart'),width,height);if(!node)return;const items=data.annualMovement,max=Math.max(...items.map((item)=>item.total),1),left=42,right=15,top=18,bottom=65,barWidth=Math.max(16,(width-left-right)/Math.max(items.length,1)-17);[0,.5,1].forEach((ratio)=>{const y=top+(height-top-bottom)*(1-ratio);line(node,{x1:left,x2:width-right,y1:y,y2:y,class:'chart-grid'});text(node,fmt(Math.round(max*ratio)),{x:left-8,y:y+4,'text-anchor':'end',class:'chart-axis'});});items.forEach((item,index)=>{const x=left+index*(width-left-right)/items.length+((width-left-right)/items.length-barWidth)/2;const scale=(height-top-bottom)/max;const newH=item.novos*scale,recH=item.recorrentes*scale;const newBar=rect(node,{x,y:top+height-top-bottom-newH,width:barWidth,height:newH,fill:COLORS.new,class:'bar'});const recBar=rect(node,{x,y:top+height-top-bottom-newH-recH,width:barWidth,height:recH,fill:COLORS.recurring,class:'bar'});[newBar,recBar].forEach((bar)=>chartEvents(bar,String(item.year),()=>`Novas: <b>${fmt(item.novos)}</b><br>Recorrentes: <b>${fmt(item.recorrentes)}</b><br>Recorrência anual: ${percent(item.percentualRecorrencia)}`));text(node,chartPeriodLabel(item.year),{x:x+barWidth/2,y:height-12,'text-anchor':'middle',class:'chart-axis'});});const legend=document.createElement('div');legend.className='legend';legend.innerHTML=`<button><span class="legend-dot" style="background:${COLORS.new}"></span>Novas</button><button><span class="legend-dot" style="background:${COLORS.recurring}"></span>Recorrentes</button>`;$('#movementChart').appendChild(legend); }

  function renderRetention() { const el=$('#retentionChart'); if(!data.retention.length){el.innerHTML='<div class="empty-data">Nenhum dado para os filtros selecionados.</div>';return;} el.innerHTML='<table class="retention-table"><thead><tr><th>Período de origem</th><th>Empresas</th><th>+1 período</th><th>+2 períodos</th><th>+3 períodos</th><th>Posteriormente</th></tr></thead><tbody>'+data.retention.map((row)=>`<tr><td><b>${row.from}</b></td><td>${row.base}</td>${row.horizons.map((item)=>`<td>${item.retained===null?'—':`<span class="heat-cell" style="display:inline-block;padding:5px;background:rgba(8,127,91,${Math.max(.08,item.percentual/100)})">${item.retained} <small>(${percent(item.percentual)})</small></span>`}</td>`).join('')}<td>${row.later ? fmt(row.later) : '—'}</td></tr>`).join('')+'</tbody></table>'; }

