  function renderProfile() { const el=$('#profileView');const profile=data?.profile;if(!profile){el.innerHTML='<div class="profile-empty">Selecione uma empresa em um gráfico ou na matriz para ver seu histórico completo.</div>';return;} el.innerHTML=`<div class="profile-header"><div class="profile-icon">${esc(profile.empresa.slice(0,1).toUpperCase())}</div><div><div class="profile-name">${esc(profile.empresa)}</div><div class="profile-types">${profile.tipos.map(esc).join(' · ')}</div></div></div><div class="profile-stats"><div class="profile-stat"><strong>${profile.anosDistintos}</strong><span>períodos distintos</span></div><div class="profile-stat"><strong>${profile.primeira}</strong><span>primeira participação</span></div><div class="profile-stat"><strong>${profile.ultima}</strong><span>última participação</span></div><div class="profile-stat"><strong>${profile.sequencia}</strong><span>maior sequência</span></div></div><div class="timeline">${YEARS.map((year)=>`<div><div class="timeline-year">${timelineLabel(year)}</div><div class="timeline-cell ${profile.periodos.includes(year)?'active':''}" title="${profile.periodos.includes(year)?'Participou em':'Sem participação em'} ${year}"></div></div>`).join('')}</div>`; }

  function renderTable() { const el=$('#tableBody');const term=state.tableSearch.toLocaleLowerCase('pt-BR').trim();let rows=data.companies.filter((item)=>!term||item.empresa.toLocaleLowerCase('pt-BR').includes(term));const key=state.sort.key;rows.sort((a,b)=>{let av=a[key],bv=b[key];if(key==='tipos') {av=a.tipos.join(' ');bv=b.tipos.join(' ');}if(Array.isArray(av)) {av=av.length;bv=bv.length;}if(typeof av==='string')return state.sort.direction*av.localeCompare(bv,'pt-BR');return state.sort.direction*((av??0)-(bv??0));});const columns=[['empresa','Empresa'],['tipos','Tipo'],['primeira','Primeira'],['ultima','Última'],['participacoes','Quantidade de Prêmios'],['sequencia','Maior seq de Anos consecutivos'],['anos','Períodos de participação']];$('#tableHead').innerHTML=columns.map(([key,label])=>`<th class="sortable" data-sort="${key}">${label} ${state.sort.key===key?`<span class="sort-arrow">${state.sort.direction===1?'↑':'↓'}</span>`:''}</th>`).join('');$('#tableHead').querySelectorAll('[data-sort]').forEach((head)=>head.addEventListener('click',()=>{const key=head.dataset.sort;if(state.sort.key===key)state.sort.direction*=-1;else{state.sort.key=key;state.sort.direction=key==='empresa'||key==='tipos'?1:-1;}renderTable();}));const pageCount=Math.max(1,Math.ceil(rows.length/state.pageSize));state.tablePage=Math.min(state.tablePage,pageCount);const visible=rows.slice((state.tablePage-1)*state.pageSize,state.tablePage*state.pageSize);el.innerHTML=visible.length?visible.map((item)=>`<tr class="clickable-row" data-company="${esc(item.empresaKey)}"><td>${esc(item.empresa)}</td><td>${item.tipos.map(esc).join('<br>')}</td><td>${item.primeira??'—'}</td><td>${item.ultima??'—'}</td><td>${item.participacoes}</td><td>${item.sequencia}</td><td>${item.periodos.join(', ')}</td></tr>`).join(''):'<tr><td colspan="7"><div class="empty-data">Nenhum registro encontrado.</div></td></tr>';el.querySelectorAll('[data-company]').forEach((row)=>row.addEventListener('click',()=>selectCompany(row.dataset.company)));$('#tableCount').textContent=`${fmt(rows.length)} empresas`;$('#pagination').innerHTML=pageCount>1?`<button class="page-button" data-page="prev" ${state.tablePage===1?'disabled':''}>Anterior</button>${Array.from({length:pageCount},(_,i)=>i+1).slice(Math.max(0,state.tablePage-3),state.tablePage+2).map((page)=>`<button class="page-button ${page===state.tablePage?'active':''}" data-page="${page}">${page}</button>`).join('')}<button class="page-button" data-page="next" ${state.tablePage===pageCount?'disabled':''}>Próxima</button>`:'';$('#pagination').querySelectorAll('[data-page]').forEach((button)=>button.addEventListener('click',()=>{const value=button.dataset.page;state.tablePage=value==='prev'?state.tablePage-1:value==='next'?state.tablePage+1:Number(value);renderTable();})); }

  function renderCompare() { const el=$('#compareView');if(!compareData){el.innerHTML='';return;}const list=(values)=>values.length?values.map((value)=>`<li title="${esc(value)}">${esc(value)}</li>`).join(''):'<li>—</li>';el.innerHTML=`<div class="compare-summary"><div class="compare-number"><strong>${compareData.both.length}</strong><span>Permaneceram</span></div><div class="compare-number"><strong>${compareData.entered.length}</strong><span>Entraram</span></div><div class="compare-number"><strong>${compareData.left.length}</strong><span>Saíram</span></div><div class="compare-number"><strong>${percent(compareData.retention)}</strong><span>Retenção</span></div></div><div class="compare-lists"><div class="compare-list"><h3>Presentes em ${compareData.yearA}</h3><ul>${list(compareData.a)}</ul></div><div class="compare-list"><h3>Presentes em ${compareData.yearB}</h3><ul>${list(compareData.b)}</ul></div><div class="compare-list"><h3>Nos dois períodos</h3><ul>${list(compareData.both)}</ul></div><div class="compare-list"><h3>Entraram em ${compareData.yearB}</h3><ul>${list(compareData.entered)}</ul></div><div class="compare-list"><h3>Saíram após ${compareData.yearA}</h3><ul>${list(compareData.left)}</ul></div></div>`; }
